void advance(double dt) {
    for (int i = 0; i < bodies.length; i++) {
        Body b = bodies[i];
        for (int j = i + 1; j < bodies.length; j++) {
            Body b2 = bodies[j];
            double dx = b.x - b2.x;
            double dy = b.y - b2.y;
            double dz = b.z - b2.z;
            double distSquared = dx*dx + dy*dy + dz*dz;
            double distance = Math.sqrt(distSquared);
            double mag = dt / (distSquared * distance);
            b.vx -= dx * b2.mass * mag;
            b.vy -= dy * b2.mass * mag;
            b.vz -= dz * b2.mass * mag;
            b2.vx += dx * b.mass * mag;
            b2.vy += dy * b.mass * mag;
            b2.vz += dz * b.mass * mag;
        }
    }
    for (Body b : bodies) {
        b.x += dt * b.vx;
        b.y += dt * b.vy;
        b.z += dt * b.vz;
    }
}

double energy() {
    double e = 0;
    for (int i = 0; i < bodies.length; i++) {
        Body b = bodies[i];
        e += 0.5 * b.mass * (b.vx*b.vx + b.vy*b.vy + b.vz*b.vz);
