            Body b2 = bodies[j];
            double dx = b.x - b2.x;
            double dy = b.y - b2.y;
            double dz = b.z - b2.z;
            double distance = Math.sqrt(dx*dx + dy*dy + dz*dz);
            e -= (b.mass * b2.mass) / distance;
        }
    }
    return e;
}
