import java.util.Locale;

public strictfp class nbody {

    private static final double SOLAR_MASS = 4 * Math.PI * Math.PI;
    private static final double DAYS_PER_YEAR = 365.24;
    private static final double DT = 0.01;
    private static final int NB = 5;

    // State arrays: index 0 = Sun, 1 = Jupiter, 2 = Saturn, 3 = Uranus, 4 = Neptune
    private static final double[] px = new double[NB];
    private static final double[] py = new double[NB];
    private static final double[] pz = new double[NB];
    private static final double[] vx = new double[NB];
    private static final double[] vy = new double[NB];
    private static final double[] vz = new double[NB];
    private static final double[] mass = new double[NB];

    private static void initBodies() {
        // Sun
        mass[0] = SOLAR_MASS;

        // Jupiter
        px[1] = 4.84143144246772090e+00;
        py[1] = -1.16032004402742839e+00;
        pz[1] = -1.03622044471123109e-01;
        vx[1] = 1.66007664274403694e-03 * DAYS_PER_YEAR;
        vy[1] = 7.66269507789657665e-03 * DAYS_PER_YEAR;
        vz[1] = -6.04699502260645784e-05 * DAYS_PER_YEAR;
        mass[1] = 9.54791938424326609e-04 * SOLAR_MASS;

        // Saturn
        px[2] = 8.34336671824457987e+00;
        py[2] = 4.12479856420656524e+00;
        pz[2] = -4.03523417114321381e-01;
        vx[2] = -2.76742510726862411e-03 * DAYS_PER_YEAR;
        vy[2] = 4.99852801234917238e-03 * DAYS_PER_YEAR;
        vz[2] = 2.30417297573763929e-05 * DAYS_PER_YEAR;
        mass[2] = 2.85885980666130812e-04 * SOLAR_MASS;

        // Uranus
        px[3] = 1.28943695621391330e+01;
        py[3] = -1.51111514016986312e+01;
        pz[3] = -2.23307578892655734e-01;
        vx[3] = 2.96460137564761618e-03 * DAYS_PER_YEAR;
        vy[3] = 2.37847173959480950e-03 * DAYS_PER_YEAR;
        vz[3] = -2.96589568540237556e-05 * DAYS_PER_YEAR;
        mass[3] = 4.36624404335156298e-05 * SOLAR_MASS;

        // Neptune
        px[4] = 1.53796971148509165e+01;
        py[4] = -2.59193146099879641e+01;
        pz[4] = 1.79258772950371181e-01;
        vx[4] = 2.68067772490389322e-03 * DAYS_PER_YEAR;
        vy[4] = 1.62824170038242295e-03 * DAYS_PER_YEAR;
        vz[4] = -9.51592254519715870e-05 * DAYS_PER_YEAR;
        mass[4] = 5.15138902046611451e-05 * SOLAR_MASS;
    }

    private static void advance(double dt) {
        // Update velocities using symmetric pair interactions
        for (int i = 0; i < NB; i++) {
            final double xi = px[i], yi = py[i], zi = pz[i];
            double vxi = vx[i], vyi = vy[i], vzi = vz[i];
            final double mi = mass[i];
            for (int j = i + 1; j < NB; j++) {
                final double dx = xi - px[j];
                final double dy = yi - py[j];
                final double dz = zi - pz[j];
                final double d2 = dx * dx + dy * dy + dz * dz;
                final double distance = Math.sqrt(d2);
                final double mag = dt / (d2 * distance);
                final double mj = mass[j];
                vxi -= dx * mj * mag;
                vyi -= dy * mj * mag;
                vzi -= dz * mj * mag;
                vx[j] += dx * mi * mag;
                vy[j] += dy * mi * mag;
                vz[j] += dz * mi * mag;
            }
            vx[i] = vxi;
            vy[i] = vyi;
            vz[i] = vzi;
        }
        // Update positions
        for (int i = 0; i < NB; i++) {
            px[i] += dt * vx[i];
            py[i] += dt * vy[i];
            pz[i] += dt * vz[i];
        }
    }

    private static double energy() {
        double e = 0.0;
        for (int i = 0; i < NB; i++) {
            e += 0.5 * mass[i] * (vx[i] * vx[i] + vy[i] * vy[i] + vz[i] * vz[i]);
            for (int j = i + 1; j < NB; j++) {
                final double dx = px[i] - px[j];
                final double dy = py[i] - py[j];
                final double dz = pz[i] - pz[j];
                final double distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
                e -= (mass[i] * mass[j]) / distance;
            }
        }
        return e;
    }

    public static void main(String[] args) {
        final long n = Long.parseLong(args[0].trim());
        initBodies();

        final StringBuilder out = new StringBuilder(64);
        out.append(String.format(Locale.US, "%.9f", energy())).append('\n');

        for (long i = 0; i < n; i++) {
            advance(DT);
        }

        out.append(String.format(Locale.US, "%.9f", energy())).append('\n');
        System.out.print(out);
    }
}
```

