        map(comp, 'M', 'K'); map(comp, 'B', 'V'); map(comp, 'V', 'B'); map(comp, 'D', 'H');
        map(comp, 'H', 'D'); map(comp, 'S', 'S'); map(comp, 'W', 'W'); map(comp, 'N', 'N');
        map(comp, 'a', 't'); map(comp, 't', 'a'); map(comp, 'c', 'g'); map(comp, 'g', 'c');
        map(comp, 'u', 'a'); map(comp, 'r', 'y'); map(comp, 'y', 'r'); map(comp, 'k', 'm');
        map(comp, 'm', 'k'); map(comp, 'b', 'v'); map(comp, 'v', 'b'); map(comp, 'd', 'h');
        map(comp, 'h', 'd'); map(comp, 's', 's'); map(comp, 'w', 'w'); map(comp, 'n', 'n');

        // Output has exactly the same size as input: every content byte maps to
        // one complemented byte, every newline to one newline.
        byte[] out = new byte[n];
        int outPos = 0;

        // Line offsets of the current sequence's lines.
        int[] ls = new int[64];
        int[] le = new int[64];
        int cnt = 0;

        int i = 0;
        while (i < n) {
            int start = i;
            while (i < n && in[i] != '\n') i++;
            int end = i;            // exclusive, newline not included
            boolean hasNl = i < n;
            if (hasNl) i++;

            if (end > start && in[start] == '>') {
                // Header: emit previous sequence (lines in reverse order,
                // each line's characters reversed and complemented).
                outPos = flush(in, comp, out, outPos, ls, le, cnt);
                cnt = 0;
                int len = end - start;
                System.arraycopy(in, start, out, outPos, len);
                outPos += len;
                if (hasNl) out[outPos++] = '\n';
            } else {
                if (cnt == ls.length) {
                    ls = Arrays.copyOf(ls, cnt << 1);
                    le = Arrays.copyOf(le, cnt << 1);
                }
                ls[cnt] = start;
                le[cnt] = end;
                cnt++;
            }
        }
        // Final sequence (may lack trailing newline on its last line).
        outPos = flush(in, comp, out, outPos, ls, le, cnt);

        OutputStream os = new BufferedOutputStream(
                new FileOutputStream(FileDescriptor.out), 1 << 16);
        os.write(out, 0, outPos);
        os.flush();
    }

    // Writes the buffered sequence lines in reverse order; each line is written
    // back-to-front with complemented bases, preserving per-line lengths
    // (and thus the original line wrapping). A trailing newline is emitted for
    // a line iff that input line was newline-terminated.
    static int flush(byte[] in, byte[] comp, byte[] out, int outPos,
                     int[] ls, int[] le, int cnt) {
        int n = in.length;
        for (int j = cnt - 1; j >= 0; j--) {
            for (int k = le[j] - 1; k >= ls[j]; k--) {
                out[outPos++] = comp[in[k] & 0xff];
            }
            if (le[j] < n) out[outPos++] = '\n';
        }
        return outPos;
    }

    static void map(byte[] comp, int from, int to) {
        comp[from] = (byte) to;
    }
}
