import java.io.FileDescriptor;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;

public class fasta {

    private static final int IM = 139968;
    private static final int IA = 3877;
    private static final int IC = 29573;

    private static int seed = 42;

    private static final String ALU_STRING =
          "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA"
        + "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT"
        + "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG"
        + "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG"
        + "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

    private static final int LINE = 60;

    private static byte[] outBuf = new byte[1 << 16];
    private static int outPos = 0;
    private static OutputStream out;

    private static void flushOut() throws IOException {
        if (outPos > 0) {
            out.write(outBuf, 0, outPos);
            outPos = 0;
        }
    }

    private static void writeString(String s) throws IOException {
        int len = s.length();
        if (outPos + len + 1 > outBuf.length) flushOut();
        for (int i = 0; i < len; i++) {
            outBuf[outPos++] = (byte) s.charAt(i);
        }
        outBuf[outPos++] = '\n';
    }

    private static void writeRepeat(byte[] alu, int n) throws IOException {
        int aluLen = alu.length;
        int srcPos = 0;
        int remaining = n;
        while (remaining > 0) {
            int len = Math.min(LINE, remaining);
            if (outPos + len + 1 > outBuf.length) flushOut();
            int first = Math.min(len, aluLen - srcPos);
            System.arraycopy(alu, srcPos, outBuf, outPos, first);
            outPos += first;
            if (first < len) {
                System.arraycopy(alu, 0, outBuf, outPos, len - first);
                outPos += len - first;
            }
            outBuf[outPos++] = '\n';
            srcPos += len;
            if (srcPos >= aluLen) srcPos -= aluLen;
            remaining -= len;
        }
    }

    private static byte[] buildTable(String chars, double[] probs) {
        int m = chars.length();
        double[] cum = new double[m];
        double c = 0.0;
        for (int i = 0; i < m; i++) {
            c += probs[i];
            cum[i] = c;
        }
        byte[] table = new byte[IM];
        for (int s = 0; s < IM; s++) {
            double r = (double) s / (double) IM;
            int j = 0;
            while (j < m - 1 && cum[j] <= r) j++;
            table[s] = (byte) chars.charAt(j);
        }
        return table;
    }

    private static void writeRandom(byte[] table, int n) throws IOException {
        int remaining = n;
        while (remaining > 0) {
            int len = Math.min(LINE, remaining);
            if (outPos + len + 1 > outBuf.length) flushOut();
            for (int i = 0; i < len; i++) {
                seed = (seed * IA + IC) % IM;
                outBuf[outPos++] = table[seed];
            }
            outBuf[outPos++] = '\n';
            remaining -= len;
        }
    }

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(args[0].trim());
        out = new FileOutputStream(FileDescriptor.out);

        byte[] alu = ALU_STRING.getBytes("ISO-8859-1");

        writeString(">ONE Homo sapiens alu");
        writeRepeat(alu, 2 * n);

        byte[] iubTable = buildTable(
            "acgtBDHKMNRSVWY",
            new double[] {0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02});
        writeString(">TWO IUB ambiguity codes");
        writeRandom(iubTable, 3 * n);

        byte[] hsTable = buildTable(
            "acgt",
            new double[] {0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008});
        writeString(">THREE Homo sapiens frequency");
        writeRandom(hsTable, 5 * n);

        flushOut();
        out.flush();
    }
}
