private static void header(String s) throws IOException {
    int len = s.length();
    if (bufPos + len + 1 > BUF.length) flushBuf();
    for (int i = 0; i < len; i++) BUF[bufPos++] = (byte) s.charAt(i);
    BUF[bufPos++] = '\n';
}
