import java.io.FileDescriptor;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

public class fasta {

    /* Linear congruential generator used by the Benchmarks Game fasta
       benchmark: seed = (seed * IA + IC) mod IM, starting from seed 42. */
    private static final int IM = 139968;
    private static final int IA = 3877;
    private static final int IC = 29573;

    private static int seed = 42;

    private static final int LINE_WIDTH = 60;

    /* 287-character ALU sequence. */
    private static final String ALU =
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA"
          + "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT"
          + "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG"
          + "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG"
          + "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

    private static final String IUB_CHARS = "acgtBDHKMNRSVWY";
    private static final double[] IUB_PROBS = {
        0.27, 0.12, 0.12, 0.27,
        0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
        0.02, 0.02, 0.02, 0.02, 0.02
    };

    private static final String HS_CHARS = "acgt";
    private static final double[] HS_PROBS = {
        0.3029549426680,
        0.1979883004921,
        0.1975473066391,
        0.3015094502008
    };

    private static OutputStream out;
    private static final byte[] BUF = new byte[1 << 16];
    private static int bufPos = 0;

    private static void flushBuf() throws IOException {
        if (bufPos > 0) {
            out.write(BUF, 0, bufPos);
            bufPos = 0;
        }
    }

    private static void writeHeader(String s) throws IOException {
        int len = s.length();
        if (bufPos + len + 1 > BUF.length) flushBuf();
        for (int i = 0; i < len; i++) {
            BUF[bufPos++] = (byte) s.charAt(i);
        }
        BUF[bufPos++] = '\n';
    }

    /* Section 1: repeat the ALU sequence to fill n characters. */
    private static void repeatFasta(byte[] alu, long n) throws IOException {
        final int aluLen = alu.length;
        int srcPos = 0;
        while (n > 0) {
            int len = (int) Math.min(LINE_WIDTH, n);
            if (bufPos + len + 1 > BUF.length) flushBuf();
            int first = Math.min(len, aluLen - srcPos);
            System.arraycopy(alu, srcPos, BUF, bufPos, first);
            bufPos += first;
            if (first < len) {
                System.arraycopy(alu, 0, BUF, bufPos, len - first);
                bufPos += len - first;
            }
            BUF[bufPos++] = '\n';
            srcPos += len;
            if (srcPos >= aluLen) srcPos -= aluLen;
            n -= len;
        }
    }

    /* Precompute, for every possible seed value, the symbol chosen for
       r = seed / IM (first cumulative probability strictly above r). */
    private static byte[] buildTable(String symbols, double[] probs) {
        int m = symbols.length();
        double[] cum = new double[m];
        double c = 0.0;
        for (int i = 0; i < m; i++) {
            c += probs[i];
            cum[i] = c;
        }
        byte[] table = new byte[IM];
        for (int s = 0; s < IM; s++) {
            double r = (double) s / IM;
            int j = 0;
            while (j < m - 1 && cum[j] <= r) j++;
            table[s] = (byte) symbols.charAt(j);
        }
        return table;
    }

    /* Sections 2 and 3: weighted random sequence of n characters. */
    private static void randomFasta(byte[] table, long n) throws IOException {
        while (n > 0) {
            int len = (int) Math.min(LINE_WIDTH, n);
            if (bufPos + len + 1 > BUF.length) flushBuf();
            for (int i = 0; i < len; i++) {
                seed = (seed * IA + IC) % IM;
                BUF[bufPos++] = table[seed];
            }
            BUF[bufPos++] = '\n';
            n -= len;
        }
    }

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(args[0].trim());
        out = new FileOutputStream(FileDescriptor.out);

        byte[] alu = ALU.getBytes(StandardCharsets.US_ASCII);

        writeHeader(">ONE Homo sapiens alu");
        repeatFasta(alu, 2L * n);

        byte[] iubTable = buildTable(IUB_CHARS, IUB_PROBS);
        writeHeader(">TWO IUB ambiguity codes");
        randomFasta(iubTable, 3L * n);

        byte[] hsTable = buildTable(HS_CHARS, HS_PROBS);
        writeHeader(">THREE Homo sapiens frequency");
        randomFasta(hsTable, 5L * n);

        flushBuf();
        out.flush();
    }
}
