```java
import java.io.BufferedOutputStream;
import java.io.FileDescriptor;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

public class mandelbrot {

    private static final int MAX_ITER = 50;
    private static final double LIMIT_SQ = 4.0; // escape radius 2, squared

    public static void main(String[] args) throws IOException {
        if (args.length == 0) {
            System.err.println("usage: mandelbrot N");
            System.exit(1);
        }
        final int N = Integer.parseInt(args[0].trim());

        // Raw buffered stream straight to stdout (no text-mode mangling).
        final OutputStream out =
                new BufferedOutputStream(new FileOutputStream(FileDescriptor.out), 1 << 16);

        // Binary PBM (P4) header: "P4\n<width> <height>\n"
        out.write(("P4\n" + N + " " + N + "\n").getBytes(StandardCharsets.US_ASCII));

        final int bytesPerRow = (N + 7) >>> 3;   // rows padded to byte boundaries
        final byte[] row = new byte[bytesPerRow];
        final int padShift = 8 - (N & 7);        // used only when N % 8 != 0

        // Precompute real part of c for each column: Re(c) = 2*x/N - 1.5  (region [-1.5, 0.5])
        final double[] crTab = new double[N];
        for (int x = 0; x < N; x++) {
            crTab[x] = 2.0 * x / N - 1.5;
        }

        for (int y = 0; y < N; y++) {
            final double Ci = 2.0 * y / N - 1.0; // Im(c) in [-1.0, 1.0)

            int byteAcc = 0;
            int bitNum = 0;
            int byteIdx = 0;

            for (int x = 0; x < N; x++) {
                final double Cr = crTab[x];
                double Zr = 0.0, Zi = 0.0, Tr = 0.0, Ti = 0.0;

                // z_{n+1} = z_n^2 + c, up to 50 iterations, escape when |z|^2 > 4
                for (int i = 0; i < MAX_ITER && Tr + Ti <= LIMIT_SQ; i++) {
                    Zi = 2.0 * Zr * Zi + Ci;
                    Zr = Tr - Ti + Cr;
                    Tr = Zr * Zr;
                    Ti = Zi * Zi;
                }

                byteAcc <<= 1;
                if (Tr + Ti <= LIMIT_SQ) byteAcc |= 1; // stayed bounded -> black pixel

                if (++bitNum == 8) {
                    row[byteIdx++] = (byte) byteAcc;
                    byteAcc = 0;
                    bitNum = 0;
                }
            }

            if (bitNum != 0) { // pad the final partial byte of the row with zero bits
                row[byteIdx] = (byte) (byteAcc << padShift);
            }

            out.write(row, 0, bytesPerRow);
        }

        out.flush();
    }
}
```

