import java.io.*;

public class mandelbrot {
    public static void main(String[] args) throws IOException {
        final int N = Integer.parseInt(args[0]);
        final int width = N, height = N;
        final int bytesPerRow = (N + 7) >> 3;

        OutputStream out = new BufferedOutputStream(System.out, 1 << 16);

        // header
        out.write(("P4\n" + N + " " + N + "\n").getBytes("ISO-8859-1"));

        // precompute Cr values
        double[] Cr = new double[N];
        for (int x = 0; x < N; x++) Cr[x] = 2.0 * x / N - 1.5;

        byte[] rowBuf = new byte[bytesPerRow];

        for (int y = 0; y < N; y++) {
            double Ci = 2.0 * y / N - 1.0;
            java.util.Arrays.fill(rowBuf, (byte) 0);
            int bitNum = 0;
            int byteIdx = 0;
            int byteAcc = 0;
            for (int x = 0; x < N; x++) {
                double Zr = 0.0, Zi = 0.0, Tr = 0.0, Ti = 0.0;
                double cr = Cr[x];
                int i = 50;
                // iterate
                while (i-- > 0 && Tr + Ti <= 4.0) {
                    Zi = 2.0 * Zr * Zi + Ci;
                    Zr = Tr - Ti + Cr[x];
                    Tr = Zr * Zr;
                    Ti = Zi * Zi;
                }
                byteAcc <<= 1;
                if (Tr + Ti <= 4.0) byteAcc |= 1;
                bitNum++;
                if (bitNum == 8) {
                    rowBuf[byteIdx++] = (byte) byteAcc;
                    byteAcc = 0;
                    bitNum = 0;
                }
            }
            if (bitNum != 0) {
                byteAcc <<= (8 - N % 8);
                rowBuf[byteIdx] = (byte) byteAcc;
            }
            out.write(rowBuf, 0, bytesPerRow);
        }
        out.flush();
    }
}
```

