        out.write(("P4\n" + N + " " + N + "\n").getBytes(StandardCharsets.US_ASCII));

        final int bytesPerRow = (N + 7) >>> 3;
        final byte[] row = new byte[bytesPerRow];
        final int padShift = 8 - (N & 7); // only used when N is not a multiple of 8

        // Precompute the real part of c for each column: Re(c) = 2*x/N - 1.5
